105	    /**
106	     * Builds the read representation of a persisted owner, populating the derived fields
107	     * ({@code householdSize}, {@code bulkSignupWarning}) that are not stored on the entity.
108	     */
109	    private OwnerDto toOwnerDtoWithDerived(Owner owner) {
110	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
113	        return ownerDto;
114	    }
