124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
127	        // Idempotent replay: a repeat with an already-seen key returns the originally created
128	        // owner with 200 rather than creating (and possibly rejecting as) a duplicate.
129	        Integer existingId = this.clinicService.findOwnerIdByIdempotencyKey(idempotencyKey);
130	        if (existingId != null) {
131	            Owner existing = this.clinicService.findOwnerById(existingId);
132	            if (existing != null) {
133	                return new ResponseEntity<>(toOwnerDtoWithDerived(existing), HttpStatus.OK);
134	            }
135	        }
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        LocalDate registrationDate = owner.resolveRegistrationDate();
139	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
140	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
141	        }
142	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
146	        // share it automatically. It feeds the membership-level cap and household sizing below.
147	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
148	        // A new owner joining an existing household (owners sharing a normalized lastName and
149	        // postcode) has its membershipLevel capped at one above the current maximum membershipLevel
150	        // among the existing household members. With no existing household member, no cap applies.
151	        owner.setMembershipLevelCap(this.clinicService.computeMembershipLevelCap(owner.getHouseholdId()));
152	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
153	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
154	        // There is no separate household-duplicate 409: two owners sharing a lastName and postcode
155	        // but differing in telephone (or email) have distinct identity keys and are allowed.
156	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        // Soft-match: the identity key differs, yet the surname's soundex and the postcode match an
160	        // existing owner, flagged 'possibleDuplicate'. This is exactly the same lastName/postcode,
161	        // different telephone case that is no longer a hard duplicate.
162	        Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
163	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
164	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
165	        owner.setNamesakeCount(
166	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
167	        this.clinicService.saveOwner(owner);
168	        this.clinicService.registerIdempotencyKey(idempotencyKey, owner.getId());
169	        OwnerDto ownerDto = toOwnerDtoWithDerived(owner);
170	        auditLogger.info(
171	            "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
173	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
