190	            ownerMapper.normalizeAddress(ownerFieldsDto.getAddress())));
191	        currentOwner.setCity(ownerFieldsDto.getCity());
192	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
193	        currentOwner.setLastName(ownerFieldsDto.getLastName());
194	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
195	        currentOwner.setEmail(ownerFieldsDto.getEmail());
196	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
197	        this.clinicService.saveOwner(currentOwner);
198	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
199	    }
