/**
 * Renders the immutable {@code OWNER_CREATED} structured audit event as a JSON object
 * {@code {seq, ownerId, customerCode, membershipLevel, event}}, stamping a fresh monotonically
 * increasing {@code seq}. The {@code identifier} is the owner's current primary identifier.
 */
private static String ownerCreatedEvent(Integer ownerId, String identifier, Integer membershipLevel) {
    return String.format(
        "{\"seq\":%d,\"ownerId\":%d,\"customerCode\":%s,\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
        eventSeq.incrementAndGet(), ownerId, jsonString(identifier), membershipLevel);
}

/** JSON-encode a nullable string value (quoted with the minimal escaping, or bare {@code null}). */
private static String jsonString(String value) {
    if (value == null) {
        return "null";
    }
    StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
    for (int i = 0; i < value.length(); i++) {
        char c = value.charAt(i);
        switch (c) {
            case '"' -> sb.append("\\\"");
            case '\\' -> sb.append("\\\\");
            case '\n' -> sb.append("\\n");
            case '\r' -> sb.append("\\r");
            case '\t' -> sb.append("\\t");
            default -> {
                if (c < 0x20) {
                    sb.append(String.format("\\u%04x", (int) c));
                } else {
                    sb.append(c);
                }
            }
        }
    }
    return sb.append('"').toString();
}

